// status codes, by value
const char* wl::status_name(long s) {
    switch (s) {
        case 1000: return "SM_SUCCESS";
        case 1001: return "SM_ERR";
        case 1002: return "SM_ERR_OUT_OF_MEMORY";
        case 1003: return "SM_ERR_UNKNOWN";
        case 1004: return "SM_ERR_FATAL";
        case 1005: return "SM_ERR_ASSERT_FAILURE";
        case 1006: return "SM_ERR_NULL_POINTER";
        case 1007: return "SM_ERR_INVALID_INPUT";
        case 1008: return "SM_ERR_NON_NULL_OUTPUT_POINTER";
        case 1010: return "SM_ERR_ASSERTVALID_FAILURE";
        case 1020: return "SM_ERR_OUTSIDE_OF_DOMAIN";
        case 1021: return "SM_ERR_NOT_WITHIN_TOLERANCE";
        case 1022: return "SM_ERR_NOT_CONVERGING";
        case 1023: return "SM_ERR_WARNING";
        case 1024: return "SM_ERR_MESSAGE";
        case 1025: return "SM_ERR_AXIS_INSIDE_FACE";
        case 1026: return "SM_ERR_LICENSE_EXPIRED";
        case 1027: return "SM_ERR_BAD_INTERSECTIONS";
        case 1028: return "SM_ERR_BAD_COINCIDENT_VERTICES";
        case 1030: return "SM_ERR_BAD_SURFACE_POINT";
        case 1032: return "SM_ERR_BAD_TANGENT_DROP";
        case 1034: return "SM_ERR_DEGENERATE_SURFACE";
        case 1036: return "SM_ERR_BAD_FIND_DEGEN_PARAM";
        case 1038: return "SM_ERR_METHOD_FAILURE_QUITING";
        case 1040: return "SM_ERR_NOTYET_HEAL_FACE";
        case 1041: return "SM_ERR_TESS_FAIL_FACE";
        default: return "SM_STATUS_UNKNOWN";
    }
}
